{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Background: There is limited evidence to evaluate the sustainability of evidence-based interventions (EBIs) for healthcare improvement.",
      "reason": "The manuscript explicitly states the current limited state of evidence about evaluating sustainability, identifying an important uncertainty in the field."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Through an integrative review, we aimed to identify approaches to evaluate the sustainability of evidence-based interventions (EBIs) and sustainability outcomes.",
      "reason": "The abstract explains the aim and rationale for conducting the review (to identify approaches and outcomes) and situates it within the problem of limited evidence and need to understand sustainability."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research.",
      "reason": "The discussion explicitly compares the review to recent syntheses and explains how this review addresses a different/remaining need, justifying the current review relative to existing reviews."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_8",
      "quote": "Integrative reviews can include diverse data sources and do not restrict the type of study design. Furthermore, integrative reviews take a more flexible approach to analysis compared to systematic reviews, combining both quantitative and qualitative data if there are similarities [12-14].",
      "reason": "The review is an integrative review of evaluation approaches rather than a review of intervention effects; therefore describing a proposed mechanism of action of an intervention is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_8",
      "quote": "Integrative reviews can include diverse data sources and do not restrict the type of study design. Furthermore, integrative reviews take a more flexible approach to analysis compared to systematic reviews, combining both quantitative and qualitative data if there are similarities [12-14].",
      "reason": "The manuscript reviews evaluation approaches for sustainability rather than evaluating a specific complex intervention or its delivery context; thus inclusion of a logic model for a specific intervention is not applicable."
    }
  ],
  "confidence": "85"
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "The aim of this integrative review was to identify and synthesize approaches that have been used to evaluate the sustainability of EBIs in healthcare. We aimed to enhance our understanding of sustainability definitions, research designs, data collection methods, timing, measures, and sustainability outcomes used for sustainability evaluation studies.",
      "reason": "The review explicitly states clear objectives/aims about identifying and synthesizing approaches and specific aspects (definitions, designs, measures, outcomes). However, the objectives are not presented using a recognised question‑formulation framework (e.g., PICO or similar), so the requirement to state objectives using a relevant framework is not fully met."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_3",
      "quote": "Through an integrative review, we aimed to identify approaches to evaluate the sustainability of evidence-based interventions (EBIs) and sustainability outcomes.",
      "reason": "This review aims to identify evaluation approaches for sustainability rather than to assess intervention effects or planned comparisons; therefore PICO-style planned comparisons for intervention effects do not apply."
    }
  ],
  "confidence": "85"
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "table_0",
      "quote": "Articles were included if they: • Were published in a peer-review journal • Were primary research • Had explicit research design and data collection methods • Had an explicit theoretical ­ approach a for sustainability ­ (theory b , ­ model c , ­ framework d , ­ instrument e , method, checklist, process, strategy, conceptual- izations, development, pilot test and/or ­ tool f ) • Were within a healthcare ­ setting g • Evaluated the sustainability of an EBI (Note that inconsistent terminology for EBI is prominent and thus may be referred to as a QI intervention/ initia- tive in the literature).",
      "reason": "Table 1 explicitly lists study characteristics used to determine eligibility including publication type (peer-review), study design (primary research with explicit design and data collection methods), requirement for an explicit theoretical approach, healthcare setting, and that studies evaluated sustainability of an EBI."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_21",
      "quote": "We only included published studies in the English language and peer-reviewed primary studies in this review. This review entailed a comprehensive search of published literature and rigorous review methods; however, we recognize that there is the possibility of incomplete retrieval of identified research. For example, all gray literature was excluded.",
      "reason": "The review specifies language (English) and publication/report status (published, peer-reviewed primary studies; gray literature excluded) but does not report any dissemination year limits; therefore eligibility criteria for report characteristics are only partially specified."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit statement distinguishes excluding studies because outcomes were not measured from excluding studies because outcome results were not reported in the provided evidence."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The evidence does not specify groups used in each synthesis nor link groups to comparisons defined in the review objectives; no synthesis groupings are described in the provided material."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although notable restrictions (e.g., English language, peer-reviewed only, exclusion of gray literature) are stated, the evidence does not provide rationales explaining these notable restrictions."
    }
  ],
  "confidence": 80
}

