    },
    {
      "element_id": "prisma_2020_10a_e2",
      "status": "PARTIAL",
      "chunk_id": "text_19",
      "quote": "Of 64 included studies, 66% ( n = 43) ... had a clear timing for evaluation and 33% ( n = 21) ... had unclear timing. Of the 43 studies with clear timing, 42% ( n = 18) evaluated sustainability at a single time point ... The remaining 57% ( n = 25) evaluated sustainability at multiple time points ... The majority of studies (63%; n = 40) conducted data collection post evaluation only ... Evaluation timing and data collection time points are provided in Table 9.",
      "reason": "The manuscript reports overall measurement timing (e.g., single vs multiple time points, pre/post) for included studies, but does not specify the time frame of measurement for each individual outcome domain."
    },
    {
      "element_id": "prisma_2020_10a_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No statement was found indicating whether all results compatible with each outcome domain (e.g., all measures, time points, analyses) were sought."
