    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was found reporting changes to outcome-domain inclusion, definitions, or importance with rationales."
    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was found reporting changes to processes for selecting results within eligible outcome domains with rationales."
    },
    {
      "element_id": "prisma_2020_10a_e7",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not report which outcomes were considered most important for interpreting conclusions nor provide a rationale for any prioritisation."
    }
