{
  "item_id": "PRISMA_2020_11",
  "elements": [
    {
      "element_id": "prisma_2020_11_e1",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "We used the Mixed Methods Appraisal Tool (MMAT) [17] to assess the methodological quality of studies.",
      "reason": "The specific risk-of-bias tool (MMAT) is explicitly named, but no version number or publication year of the MMAT is reported in the provided evidence."
    },
    {
      "element_id": "prisma_2020_11_e2",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "The MMAT [17] appraises the quality by study design type, such as quantitative, qualitative, or mixed empirical methods. We distinguished mixed-methods as studies combining both qualitative and quantitative methods, whereas studies classified as multi-methods used 2 + qualitative methods. The criteria are specific to each type of study, with five domains apportioned to qualitative studies and quantitative studies subdivided into randomized controlled, non-randomized and descriptive studies.",
      "reason": "The domains/components assessed by the MMAT are described (design-specific criteria, five domains for qualitative, and subdivisions for quantitative study types)."
    },
    {
      "element_id": "prisma_2020_11_e3",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "Each study is assigned an overall quality score, using asterisks representing the quality appraisal of each study. Scores vary from 20% (*) when one criterion is met to 100% (*****) when all criteria are met.",
      "reason": "An overall risk-of-bias/quality judgement (an overall quality score expressed with asterisks and percentage equivalents) is reported, including the scoring rules linking number of criteria met to percentage/asterisk ratings."
    },
    {
      "element_id": "prisma_2020_11_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No information is provided in the retrieved evidence about any adaptations made to the MMAT or other risk-of-bias tools."
    },
    {
      "element_id": "prisma_2020_11_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review used an existing tool (MMAT); there is no indication that a newly developed risk-of-bias tool was created for this study."
    },
    {
      "element_id": "prisma_2020_11_e6",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "Two reviewers independently completed MMAT assessments and compared scoring.",
      "reason": "The number of reviewers and that they worked independently is reported. However, a detailed disagreement-resolution procedure (e.g., third reviewer adjudication or predefined consensus process) is not described beyond stating that they compared scoring."
